      "丰收之怒": "Ira da Colheita",
      "每3个敌方行动回合，使场上所有熊族随从获得+1/+2。": "A cada 3 turnos de ação inimigos, dá a todos os lacaios urso no campo de batalha +1/+2.",
      "碧露大贤者·涅芙莉": "Grande Sábia Nephrie do Orvalho Azul",
