      "每3个敌方回合，在空位免费召唤1只幼狼。": "A cada 3 turnos inimigos, invoca 1 Filhote de Lobo em um espaço vazio gratuitamente.",
      "裂月咆哮": "Uivo da Lua Rasgada",
      "每4个敌方回合，使所有狼类随从永久获得+1攻击。": "A cada 4 turnos inimigos, todos os lacaios lobo ganham permanentemente +1 de Ataque.",
      "银灰狼女猎手": "Caçadora Lobo Cinzento-Prata",
      "千枝城的灰牙首领": "Líder Greyfang da Cidade dos Mil Galhos",
      "避开翡翠城追兵、占据千枝城废墟的狼族首领。每回合都会呼唤一只迅猛的灰狼投入战斗。": "A chefe lobo que escapou dos perseguidores da Cidade Esmeralda e conquistou as ruínas da Cidade dos Mil Galhos. A cada turno ela chama um lobo cinzento ágil para a batalha.",
