      "第五关剧情结束后驻扎于千枝城的魔族据点。随从均为20攻/200血，属于长期挑战内容。": "O reduto demoníaco estacionado na Cidade dos Mil Galhos após a história do Capítulo 5. Todos os lacaios são 20/200 — conteúdo de desafio de longo prazo.",
