      "麦田稻草魔像": "Golem de Palha do Campo de Trigo",
      "留守的农民夫妇": "O Casal de Fazendeiros Que Ficou",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "Acalme-se, jovem. Esses ursos não mataram ninguém aqui. Quando chegaram à fazenda, apenas afastaram os aldeões em direção à capital real.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "Ficamos porque nunca sentimos nenhuma hostilidade deles. No início eles nem sabiam como segurar um arado — apenas revolveram os campos em um caos pela força bruta.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "Depois ensinamos aos homens urso a reparar os canais e semear trigo, e ensinamos às mulheres urso a cuidar das colmeias e trazer a colheita. Eles aprendem lentamente, mas nunca desperdiçam comida.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "Eles poupam o lugar mais quente do celeiro para seus filhotes, e trazem o primeiro saco de trigo novo para nossa porta. Pelo menos em nossos olhos, eles não são tão viles quanto as lendas dizem.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "Se você deve seguir adiante, veja com seus próprios olhos antes de julgar. O que aconteceu aqui pode não ser um simples caso de monstros conquistando uma aldeia.",
