      "市集、印刷术与允许异族登台的演出许可": "Mercados, impressão e licenças de performance que deixam outras raças ocuparem o palco",
      "血斧角斗场": "Arena Machado-Sangrento",
      "裁判最好离远点，我的胜利通常会溅到前三排": "O árbitro deve se afastar—minhas vitórias geralmente salpicam as primeiras três fileiras",
