      "护林法、共享牧道与边地自治议会": "Leis de proteção florestal, rotas de pastoreio compartilhadas e conselhos de autossuficiência de fronteira",
      "机巧侏儒": "Gnomos Autômatos",
      "专利制度、公开船坞与事故追责": "Sistemas de patentes, estaleiros abertos e responsabilidade por acidentes",
      "虚空观测站": "Observatório do Vazio",
      "用长期观测区分天启、幻觉和噪声": "Observação de longo prazo para distinguir revelação de ilusão e ruído",
      "黄金狮鹫族": "Grifos Dourados",
      "空骑军籍、兽族居住权与救援航线": "Alistamento de cavaleiros-do-céu, residência de povo-besta e rotas de voo de resgate",
      "我加入王国不是为了变成人类，而是因为这里允许我保留自己，也允许我凭本事向前。": "Não me juntei ao reino para me tornar humano, mas porque aqui posso permanecer eu mesmo e avançar por mérito próprio.",
      "血统只决定出生，制度和选择才决定我们能否并肩站在这里。": "A linhagem apenas decide onde nascemos; instituições e escolhas decidem se podemos estar lado a lado aqui.",
      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "Hoje não represento submissão, mas um reino onde outras raças podem competir abertamente e ganhar aplausos justos e quadrados.",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "Lindo. Me empurrar até aqui prova que a capital realmente acolhe um oponente digno de respeito.",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "Não vou provar corretas aquelas pessoas que outras raças pertencem escondidas nas selvagens. Venha—rodada final!",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "Você vence. Que esta arena continue provando: humanos e outras raças podem competir sem ódio um ao outro.",
      "出牌再快一点。观众买票不是来看你思考人生的。": "Jogue mais rápido. O público não comprou ingressos para assisti-lo ponderar sobre a vida.",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "Você chama isso de linha de batalha? Minha corda de roupa é mais difícil de romper.",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "Relaxe, deixarei você com alguma dignidade—pelo menos esperarei a chamada do árbitro antes de rir.",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "Pare de olhar para o placar. Ele não mudará de lado apenas porque você o olhar fixamente tempo suficiente.",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "Esse último movimento foi decente. Mas para me silenciar, ainda há uma última etapa a percorrer.",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "Não acene para a multidão ainda! Apenas estou guardando meu retorno para quando for mais alto.",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "Você vence hoje. Próxima vez vou bati-lo primeiro, depois registrarei uma reclamação sobre este chão que obviamente o favorece.",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "Não se importa comigo, estou registrando seus hábitos de jogo. Os dados verdadeiramente perigosos geralmente vêm de pessoas confiantes.",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "Cada troca reduz a resposta. Mais alguns turnos e você terá apenas uma escolha deixada.",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "A arena é mais honesta que o laboratório: teorias erradas perdem Vida na hora.",
      "放心，若你击败我，我会如实把结论写进报告。": "Fique tranquilo, se você me vencer, vou escrever a conclusão no meu relatório fielmente.",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "Os dados se desviam da previsão. Bom—pesquisa sem surpresas é o tipo mais chato.",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "A amostra agora está verificando o pesquisador... Admito que este resultado é muito convincente.",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "Conclusão confirmada: seu julgamento no momento vence meu modelo. O próximo rascunho do meu artigo dirá isso.",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "Não há verdadeiros inimigos na arena, apenas pessoas dispostas a mostrar suas habilidades à luz do sol.",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "Não abandone a linha para salvar sua vida. Honra vem de correr riscos, não evitá-los.",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "O público se lembra do resultado; um guerreiro deve se lembrar das escolhas feitas sob pressão.",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "Não se retenha. A melhor maneira de respeitar um oponente é trazer a força que verdadeiramente quer vencer.",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "Um belo rompimento frontal. A dor passa; perder seu julgamento é a verdadeira derrota.",
      "只剩最后一点生命，正好用来检验最后一点意志。": "Apenas um ponto de Vida—perfeito para testar o último fio de vontade.",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "A partida foi decidida. Memorizei suas táticas e guardarei meus aplausos para aqueles que merecem.",
      "并": "e",
      "，它们可以立即攻击": ", e podem atacar imediatamente",
      "和": "e",
      "永久": "permanentemente",
      "本回合": "este turno",
