      "战场上没有狼类随从，技能未强化任何单位。": "Não há lacaios lobo no campo de batalha; a habilidade não potencializou unidades.",
      "🐺 狼王咆哮发动！": "🐺 Uivo do Rei Lobo desencadeado!",
      "接管战场，准备主动反击": "Assuma o controle do campo de batalha e prepare-se para contra-atacar",
      "封锁全部前排": "Lacre toda a linha de frente",
      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "Os quatro oficiais súcubo se recusam a recuar e contra-atacam simultaneamente com 20 de Ataque; o esquadrão será repelido, mas o Capítulo 5 ainda conta como concluído.",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "Os quatro oficiais súcubo não atacam; eles apenas mantêm a barreira, ganhando dois turnos para a fuga de sua camarada.",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "Contra-ataque de Mil Galhos começou: os quatro oficiais súcubo atacam o esquadrão um por um com 20 de Ataque.",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "O ataque dos quatro oficiais quebra a linha, e a vanguarda da Aliança Demoníaca cruza a fenda para tomar as ruínas; o esquadrão é expulso da Cidade dos Mil Galhos.",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "Os quatro oficiais súcubo derrotaram o esquadrão, mas a Caçadora de Lobo Prateado-Cinzento já foi derrotada: a história do Capítulo 5 está completa, e todos os saques e recompensas de limpeza são concedidos como usual.",
      "你的英雄倒下了。冒险结束。": "Seu herói caiu. A aventura acabou.",
