      "追寻银灰狼女猎手": "Rastreie a Caçadora Lobo Cinzento Prateado",
      "追寻碧露大贤者": "Procure o Grande Sábio do Orvalho Azul",
      "踏入金麦农场": "Entre na Fazenda de Trigo Dourado",
      "会见丰穗战母": "Encontre a Mãe da Guerra da Colheita",
      "进军王庭": "Marche para a Corte",
      "挑战翠影女王": "Desafie a Rainha da Sombra Esmeralda",
      "击穿战线": "Rompa a Linha de Batalha",
      "直面狼王": "Enfrente o Rei Lobo",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "O Capítulo 5 está situado nas ruínas antigas ao sul da Cidade Esmeralda. Lobos cinzentos e outras bestas expandem seu território com velocidade e emboscadas; no final você enfrenta a Caçadora Lobo Cinzento Prateado.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "O Capítulo 4 tem vinte nós chefes de lodo. Eles têm Vida espessa, Ataque baixo e continuam se regenerando; siga o riacho brilhante nas profundezas da floresta para enfrentar a Grande Sábia Nephrie do Orvalho Azul.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "O Capítulo 3 tem vinte nós chefes de urso e uma fazenda. Siga as trilhas da fazenda para investigar a aldeia ocupada, e finalmente enfrente a Mãe da Guerra da Colheita Breya.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "O Capítulo 2 tem vinte nós chefes. Avance pelas defesas do exército goblin e finalmente enfrente a Rainha da Sombra Esmeralda com 200 de Vida.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "Distribua seu exército em quatro rotas de batalha com linhas de frente e de trás, abra uma brecha e atravesse treze nós da Floresta Brumosa. Toda vitória se torna força para a próxima expedição.",
      "重新开始本关": "Reiniciar Este Capítulo",
