      "战斗经验、法力和技能成长会跨冒险保存。": "Experiência de Batalha, mana e crescimento de habilidade se carregam entre aventuras.",
      "曾任王都护卫队长。野兽接连觉醒后，他认为只守住一座王都远远不够，于是离开王都、集结自己的小队，奔赴各地平定乱局。": "Foi capitão da Guarda Real da capital. Quando as feras começaram a despertar uma após a outra, concluiu que proteger uma única capital não bastava: deixou-a, reuniu seu próprio esquadrão e partiu para conter os distúrbios por toda a terra.",
