      "（已拥有）": "(já possuído)",
      "已加入英雄技能收藏，可在英雄档案装备。": "Adicionado à sua coleção de habilidades de herói; equipe-o no Perfil do Herói.",
      "，你成为本届王冠杯冠军！": ", você é o campeão da Copa da Coroa deste ano!",
