      "本届赛事已经结束，已获得的晋级奖金全部保留。": "Este torneio acabou; todos os prêmios de avanço que você ganhou são mantidos.",
      "查看赛果": "Ver Resultados",
      "魔族重建据点": "Fortaleza Demoníaca Reconstruída",
      "· 尚未挑战": "· ainda não foi desafiado",
