      "已击败的节点、路线解锁和本轮奖励都会保留。之后点击“继续游戏”即可从当前进度继续。": "Nós derrotados, rotas desbloqueadas e as recompensas desta rodada são todas mantidas. Clique em \"Continuar\" mais tarde para retomar a partir de seu progresso atual.",
