      "只留下最终首领？": "Deixar apenas o chefe final?",
      "将第五关设置为前19个首领已经击败，只留下银灰狼女猎手。英雄、金币、收藏、卡组以及其他关卡存档均不会改变。": "Define o Capítulo 5 para que os primeiros 19 chefes sejam derrotados, deixando apenas a Caçadora Lobo Cinzenta Prateada. Seu herói, ouro, coleção, baralho e outros salvamentos do capítulo não vão mudar.",
