      "{0}已被第五名军官救走。四名20攻/200血军官拒绝撤离，正在直接杀退小队。": "{0} foi resgatado pelo quinto oficial. Os quatro oficiais 20/200 se recusam a se retirar e estão atacando o esquadrão diretamente.",
      "{0}已被第五名军官带走。四名10攻/200血军官封锁前排，并将在{1}回合后撤离。": "{0} foi levado pelo quinto oficial. Os quatro oficiais 10/200 selam a linha de frente e se retirarão em {1} turnos.",
