      "· 英雄生命 {0}/{1}，同时恢复满生命": "· Vida do Herói {0}/{1}, também totalmente restaurada",
      "每回合恢复至 {0}/{1}。永久上限不封顶，只能由统领试炼首次通关提升。": "Restaura para {0}/{1} cada turno. O limite permanente não tem limites e pode apenas ser aumentado pelas primeiras limpezas das Provas do Comandante.",
