      "森灵德鲁伊": "Druida do Bosque",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "A atiradora mais jovem da fronteira florestal; suas flechas atravessam camadas de galhos para encontrar inimigos escondidos atrás das linhas.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "Uma bruxa que deixou a torre de magos para estudar a Fenda sozinha; divide a mana em incontáveis projéteis difíceis de evitar.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "Uma santa enviada à linha de frente pelo Templo do Sol; acredita que todo soldado merece se reerguer.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "Um senhor da guerra das tribos do norte que acende a fúria de seus guerreiros com o próprio sangue.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "Líder dos patrulheiros de Bosque-lunar; sempre faz o inimigo ver arqueiros nas sombras onde não deveria haver nenhum.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "Veterano da Ordem da Aurora da capital; sua parede de escudos nunca recuou um passo.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "Uma druida nascida do coração do bosque antigo; cada muda que planta cresce e se torna uma árvore ancestral que guarda a floresta.",
      "穿林箭": "Flecha perfurante",
      "奥术飞弹": "Mísseis arcanos",
      "晨曦复苏": "Renascer da aurora",
      "血怒狂击": "Frenesi de sangue",
      "林间伏兵": "Emboscada na floresta",
      "圣盾壁垒": "Muralha égide",
      "萌芽古树": "Árvore ancestral brotando",
      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "Ignorando a proteção da linha de frente, causa {0} de dano a qualquer lacaio inimigo; se ele morrer, compre 1 carta.",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "Dispara {0} mísseis arcanos; cada um causa 1 de dano a um lacaio inimigo ou ao herói inimigo aleatório.",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "Restaura totalmente a vida de todos os lacaios aliados e restaura {0} de vida ao seu herói.",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "Seu herói perde 2 de vida; um lacaio aliado recebe +{0} de ataque neste turno e pode atacar novamente de imediato.",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "Invoca na retaguarda um Arqueiro Sombra-folha à distância {0}/{1}; ele pode atacar lacaios imediatamente.",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "Todos os lacaios aliados da linha de frente recebem +{0} de vida permanente; se sua linha de frente estiver vazia, invoca um Guardião Égide 0/{1}.",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "Invoca uma Muda Ancestral {0}/{1}; no início de cada um dos seus turnos, ela recebe +1/+1 permanente.",
